'use strict';
/* El Claro de las Bestias (10/11, pedido del dueño: "la parte de la cueva de los osos y lobos donde encontramos a Urso, un
   exterior con referencias a combates entre orcos y osos, y la entrada a la cueva parecida a la boca de un oso; grande y
   explorable"; "la entrada a la cueva es al noroeste… la cueva debe estar siguiendo ese sentido").
   Mapa nuevo del Taller (claro_de_las_bestias, 1436×802, piezas ed_cb_*), de las tres capas de Nano Banana Pro que mandó
   el dueño. Se llega por el camino del norte de las Tierras Orcas y se entra abajo a la derecha; el camino cruza el
   campo de batalla de orcos y osos (el esqueleto del oso gigante, la torre orca caída, el campamento destrozado) y sube
   hacia el noroeste hasta la cueva con forma de boca de oso (arriba a la izquierda).
   - Tierras Orcas, borde norte (el camino del norte, x 762) ↔ Claro, borde sur (el camino, x 1232).
   - La jaula de Urso pasa de las Tierras al campamento orco destrozado del Claro (ck_heroe_oso.js la busca acá).
   - Bestias: huargos, jabalíes, hombres lobo y un hombre oso; de noche, más lobos.
   - La boca de la cueva todavía no se abre (la cueva va en otro mapa): T muestra el cartel.
   Va ANTES de ck_heroe_oso.js (que mira CK_CLARO_BESTIAS para saber dónde va la jaula).
   Borrar su línea de index.html saca la salida de las Tierras al Claro (y la jaula vuelve a las Tierras). */
window.CK_CLARO_MINI = 'data:image/png;base64,';   // el dibujo del minimapa (el mapa a 1/4)
(function () {
  if (typeof MainGameScene === 'undefined' || typeof INTERIOR_LAYOUTS === 'undefined') return;
  const D = window.EDITOR_DATA, ID = 'claro_de_las_bestias', TIERRAS = 'tierras_orcas';
  if (!D || !D.mapas || !D.mapas[ID] || !INTERIOR_LAYOUTS['ed_' + ID]) return;
  const Z = 'ed_' + ID + '.main';
  const LUGAR = { jaula: { x: 689, y: 604 }, boca: { x: 344, y: 236 } };
  window.CK_CLARO_BESTIAS = { ID, Z, LUGAR };   // ck_heroe_oso.js pone acá la jaula de Urso

  // conexión con las Tierras: el camino del norte de las Tierras sale al camino del Claro (abajo a la derecha)
  const LLEGA = { claro: { x: 1232, y: 766 }, tierras: { x: 762, y: 46 } };
  const P = MainGameScene.prototype;
  const LT = INTERIOR_LAYOUTS['ed_' + TIERRAS];
  if (LT) INTERIOR_LAYOUTS['ed_' + TIERRAS] = function (kit) {
    const r = LT.apply(this, arguments), a = kit.areas && kit.areas.main;
    if (a) (a.exits = a.exits || []).push({ x: LLEGA.tierras.x - 30, y: 0, w: 60, h: 18, key: 'walk', to: 'cb_claro', hint: '▲ Claro de las Bestias' });
    return r;
  };
  const cambiar0 = P.switchInteriorArea;
  P.switchInteriorArea = function (nombre) {
    if ((nombre === 'cb_claro' || nombre === 'cb_tierras') && this._gameMode === 'campaign') {
      if (!this._doorTransition && this.ckEntrar) this.ckEntrar(nombre === 'cb_claro' ? ID : TIERRAS, nombre === 'cb_claro' ? LLEGA.claro : LLEGA.tierras);
      return;
    }
    return cambiar0.apply(this, arguments);
  };
  let registrado = false;
  const registrar = () => {     // la pantalla de carga se carga después de este archivo
    if (registrado) return; registrado = true;
    try { const C = window.CK_PANTALLA_CARGA; if (C && C.REGION) C.REGION.unshift([/^claro_de_las_bestias$/, 'Las Tierras Salvajes']); } catch (e) {}
  };
  document.addEventListener('DOMContentLoaded', registrar);

  const L0 = INTERIOR_LAYOUTS['ed_' + ID];
  INTERIOR_LAYOUTS['ed_' + ID] = function (kit) {
    const r = L0.apply(this, arguments), a = kit.areas && kit.areas.main;
    if (a) {
      registrar();
      ['talkers', 'fx', 'colliders', 'exits'].forEach(k => (a[k] = a[k] || []));
      a.exits.push({ x: LLEGA.claro.x - 36, y: 802 - 18, w: 72, h: 18, key: 'walk', to: 'cb_tierras', hint: '▼ Tierras Orcas' });
      a.talkers.push({ x: LUGAR.boca.x, y: LUGAR.boca.y, r: 44, lines: ['La boca de la cueva de Garra Negra: colmillos de piedra y zarpazos en la roca. Adentro está negro como la noche… todavía no te animás a entrar'] });
      a.talkers.push({ x: 1100, y: 400, r: 56, lines: ['El esqueleto de un oso gigante, con una lanza orca entre las costillas. Acá pelearon orcos y osos'] });
      a.talkers.push({ x: 655, y: 270, r: 52, lines: ['Un círculo de piedras con cráneos de oso: la manada marca acá su territorio'] });
      a.talkers.push({ x: 470, y: 585, r: 50, lines: ['Un campamento orco destrozado. Las estacas tienen zarpazos enormes'] });
      a.talkers.push({ x: 300, y: 500, r: 44, lines: ['Una guarida de lobos bajo las raíces de un árbol caído. Huele a carne'] });
      a.talkers.push({ x: 170, y: 560, r: 40, lines: ['Colmenas silvestres y moras. A los osos les encanta la miel'] });
      a.talkers.push({ x: 1265, y: 600, r: 44, lines: ['Una torre de vigía orca, tirada abajo de un zarpazo'] });
      a.fx.push({ type: 'dust', x: 900, y: 420, w: 536, h: 382 });
      a.colliders.push({ x: 952, y: 632, w: 48, h: 42 });     // el pozo de estacas
    }
    return r;
  };
  if (typeof ZONE_ENEMIES !== 'undefined') {
    ZONE_ENEMIES[Z] = [['warg', 820, 340, 50], ['warg', 900, 300, 50], ['boar', 1120, 220, 60], ['werewolf', 560, 470, 50],
      ['warg', 300, 600, 40], ['werebear', 1050, 540, 50], ['boar', 260, 360, 40], ['werewolf', 1000, 170, 60, 'night'], ['warg', 700, 450, 60, 'night']]
      .filter(e => ENEMY_TYPES[e[0]]);
  }
  // minimapa: el dibujo del mapa a 1/4 (como la Frontera)
  try {
    const MM = window.CK_MINIMAPA, A = window.EDITOR_ASSETS || {};
    if (MM && MM.Z) {
      MM.Z[Z] = { img: ID, esc: 4, w: 1436, h: 802, ext: 1, n: 'Claro de las Bestias', g: 'Tierras Salvajes' };
      if (MM.L) {
        MM.L[Z] = [{ n: 'Boca de la cueva', x: LUGAR.boca.x, y: LUGAR.boca.y - 20, ic: 'estrella' }, { n: 'Campo de batalla', x: 1100, y: 380, ic: 'estrella' },
          { n: 'Jaula de Urso', x: LUGAR.jaula.x, y: LUGAR.jaula.y - 30, ic: 'estrella' }, { n: 'Tierras Orcas', x: 1232, y: 796, ic: 'flecha', d: 's', va: 'ed_' + TIERRAS + '.main' }];
        const T = MM.L['ed_' + TIERRAS + '.main'];
        if (T && !T.some(l => l.va === Z)) T.push({ n: 'Claro de las Bestias', x: 762, y: 6, ic: 'flecha', d: 'n', va: Z });
      }
      if (MM.dibujo && window.CK_CLARO_MINI) MM.dibujo(ID, window.CK_CLARO_MINI);
    }
  } catch (e) {}
})();
